   118|async function tick(): Promise<void> {
   119|  const tasks = await listTasks(50);
   120|  const candidates = tasks.filter((t) => {
   121|    // Mark senior_dev tasks via trace_id (always "senior-dev-..." from the
   122|    // submit endpoint) because the task_type column is only created by the
   123|    // self-bootstrap DDL, which requires SUPABASE_ACCESS_TOKEN and may not have
   124|    // run yet. trace_id is in the original CREATE TABLE and is always present,
   125|    // so it is the reliable marker. task_type is checked too as a fallback.
   126|    const isSeniorDev = (t.task_type === 'senior_dev')
   127|      || (typeof t.trace_id === 'string' && t.trace_id.startsWith('senior-dev-'));
   128|    if (!isSeniorDev) return false;
   129|    if (t.status !== 'QUEUED' && t.status !== 'RETRYING') return false;
   130|    if (t.assigned_worker_id && t.assigned_worker_id !== IVX_SENIOR_DEV_WORKER_ID) return false;
   131|    return true;
   132|  });
   133|
   134|  if (candidates.length === 0) return;
   135|
   136|  const task = candidates.sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())[0];
   137|  if (!task) return;
   138|
   139|  const claimed = await claimTask(task.id);
   140|  if (!claimed) return;
   141|
   142|  state.currentTaskId = task.id;
   143|  state.runCount += 1;
   144|
   145|  try {
   146|    await executeSeniorDevTask(claimed);
   147|  } catch (error) {
   148|    state.errorCount += 1;
   149|    console.log('[IVX-SENIOR-DEV-01] executeSeniorDevTask error:', error instanceof Error ? error.message : 'unknown');
   150|    await failTask(task.id, error instanceof Error ? error.message : 'unknown');
   151|  } finally {
   152|    state.currentTaskId = null;
   153|    state.currentPhase = null;
   154|  }
   155|}
