   157|async function claimTask(taskId: string): Promise<IVXOwnerAITaskRow | null> {
   158|  const now = new Date().toISOString();
   159|  // The submit endpoint pre-assigns assigned_worker_id='IVX-SENIOR-DEV-01' so the
   160|  // task is already bound to this worker. The optimistic claim must therefore
   161|  // accept rows where assigned_worker_id IS NULL (unassigned) OR already equals
   162|  // IVX-SENIOR-DEV-01 (pre-assigned to us). Using PostgREST or= syntax.
   163|  const filter = `&status=in.(QUEUED,RETRYING)&or=(assigned_worker_id.is.null,assigned_worker_id.eq.${encodeURIComponent(IVX_SENIOR_DEV_WORKER_ID)})`;
   164|  const patched = await patchTask(taskId, {
   165|    status: 'RUNNING',
   166|    checkpoint: `CLAIMED by ${IVX_SENIOR_DEV_WORKER_ID}`,
   167|    assigned_worker_id: IVX_SENIOR_DEV_WORKER_ID,
   168|    heartbeat_at: now,
   169|    checkpoint_history: appendCheckpoint(null, `CLAIMED by ${IVX_SENIOR_DEV_WORKER_ID} at ${now}`),
   170|  }, filter);
   171|  return patched;
