   183|/**
   184| * The full autonomous engineering pipeline with REAL tools.
   185| */
   186|async function executeSeniorDevTask(task: IVXOwnerAITaskRow): Promise<void> {
   187|  const run = await writeProofLedger({
   188|    taskId: task.id,
   189|    workerId: IVX_SENIOR_DEV_WORKER_ID,
   190|    status: 'running',
   191|    repository: process.env.GITHUB_REPO_URL ?? undefined,
   192|  });
   193|  if (!run) {
   194|    // Proof ledger write failed (table missing / Supabase unreachable). This is
   195|    // a hard failure for a senior_dev task — without a ledger there is no honest
   196|    // evidence trail. Do NOT fall through to a hollow VERIFIED. Fail loudly.
   197|    throw new Error('Failed to create proof ledger run record (ivx_senior_dev_worker_runs table unreachable — check SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY + ensureSeniorDevTables bootstrap).');
   198|  }
   199|  const runId = run.id;
   200|  // Patch the proof_ledger_id back onto the task so callers can join ledger ↔ task.
   201|  await patchTask(task.id, { proof_ledger_id: runId });
   202|
   203|  // ─── Phase 1: PLANNING ──────────────────────────────────────────────
   204|  await setPhase(task.id, 'PLANNING', runId);
   205|  // Fetch the real repo file tree so the AI plans against actual files
   206|  // (not hallucinated paths like src/chat/ChatService.js that don't exist).
   207|  const fileTreeResult = await githubListFiles();
   208|  const repoFileTree = fileTreeResult.ok ? fileTreeResult.files.slice(0, 400) : [];
   209|  await logCheckpoint(task.id, runId, 'PLANNING', { repoFileCount: repoFileTree.length, fileTreeOk: fileTreeResult.ok, fileTreeError: fileTreeResult.error });
   210|  const planResult = await planEngineeringTask(task.prompt, repoFileTree);
   211|  let plan: EngineerPlan;
   212|  if (planResult.ok && planResult.content) {
   213|    plan = parsePlan(planResult.content, task.prompt);
   214|  } else {
   215|    // AI planning failed. The owner forbade fake/hollow VERIFIED certifications.
   216|    // Instead of silently falling back to an audit-only path that reaches VERIFIED
   217|    // with no real work, FAIL the task honestly with the AI planning error so the
   218|    // owner sees exactly why the autonomous worker could not proceed.
   219|    const planningError = planResult.error ?? 'AI planning returned empty content';
   220|    await failTask(task.id, `PLANNING failed: ${planningError}`);
   221|    await updateProofLedger(runId, { status: 'failed', errorMessage: `PLANNING failed: ${planningError}` });
   222|    return;
   223|  }
   224|  await logCheckpoint(task.id, runId, 'PLANNING', { plan });
   225|  await updateProofLedger(runId, { logs: [`plan: ${plan.summary}`] });
   226|
   227|  // ─── Phase 2: INSPECTING ────────────────────────────────────────────
   228|  await setPhase(task.id, 'INSPECTING', runId);
   229|  const fileContents: Map<string, string> = new Map();
   230|  for (const filePath of plan.filesToInspect) {
   231|    const file = await githubReadFile(filePath);
   232|    if (file.ok && file.content !== null) {
   233|      fileContents.set(filePath, file.content);
   234|    }
   235|  }
   236|  await logCheckpoint(task.id, runId, 'INSPECTING', { files: plan.filesToInspect, readCount: fileContents.size });
   237|  await updateProofLedger(runId, { filesInspected: plan.filesToInspect });
   238|
   239|  // ─── Phase 3: IMPLEMENTING ──────────────────────────────────────────
   240|  await setPhase(task.id, 'IMPLEMENTING', runId);
   241|  const changedFiles: string[] = [];
   242|  let localEdits: { path: string; content: string }[] = [];
   243|
   244|  for (const fileChange of plan.filesToChange) {
   245|    // CRITICAL: always read the current file content from GitHub before generating
   246|    // a patch. If the AI listed the file in filesToChange but NOT in filesToInspect,
   247|    // the fileContents map would be empty, and generateFilePatch would get current=''
   248|    // — causing it to hallucinate the full file from scratch (which breaks tsc/tests).
   249|    let current = fileContents.get(fileChange.path) ?? '';
   250|    if (!current) {
   251|      const readFile = await githubReadFile(fileChange.path);
   252|      if (readFile.ok && readFile.content !== null) {
   253|        current = readFile.content;
   254|        fileContents.set(fileChange.path, current);
   255|        await logCheckpoint(task.id, runId, 'IMPLEMENTING', { file: fileChange.path, note: 'fetched current content from GitHub (not in filesToInspect)' });
   256|      } else {
   257|        await logCheckpoint(task.id, runId, 'IMPLEMENTING', { file: fileChange.path, error: 'Could not read current file content from GitHub', githubError: readFile.error });
