   259|      }
   260|    }
   261|    const patchResult = await generateFilePatch({
   262|      filePath: fileChange.path,
   263|      currentContent: current,
   264|      goal: `${task.prompt}\n\nReason for this file: ${fileChange.reason}`,
   265|      priorContext: plan.summary,
   266|    });
