   268|    if (!patchResult.ok || !patchResult.content) {
   269|      await logCheckpoint(task.id, runId, 'IMPLEMENTING', { file: fileChange.path, error: patchResult.error ?? 'AI returned empty content' });
   270|      continue;
   271|    }
   272|
   273|    const newContent = stripCodeFences(patchResult.content);
   274|    // Write locally so tests can run against the change.
   275|    writeLocalFile(fileChange.path, newContent);
   276|    localEdits.push({ path: fileChange.path, content: newContent });
   277|    changedFiles.push(fileChange.path);
