  method: "POST",
  headers: { "Authorization": "Bearer " + ownerAt, "Content-Type": "application/json" },
  body: JSON.stringify({
    action: "render_get_deploys",
    input: { limit: 3 },
    confirm: false
  }),
});
const d3 = await r3.json();
console.log("DEPLOYS_HTTP=" + r3.status, "ok=" + d3.ok, "error=" + (d3.error ?? "").slice(0,150));
if (d3.ok && d3.deploys) {
  for (const d of d3.deploys.slice(0,3)) {
    console.log("DEPLOY id=" + d.id + " status=" + d.status + " commit=" + (d.commit?.id ?? ".")?.slice(0,12) + " createdAt=" + d.createdAt);
  }
} else {
  console.log("FULL=" + JSON.stringify(d3).slice(0,300));
}
' 2>&1 | head -12

